entryLen = input(20, "Entry Channel", 2, 100, 1)
exitLen = input(10, "Exit Channel", 2, 100, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

entryLevel = highest(high, entryLen)[1]
exitLevel = lowest(low, exitLen)[1]

var inPos = 0.0

buySig = close > entryLevel and inPos[1] == 0.0 and bar_index > entryLen
sellSig = close < exitLevel and inPos[1] == 1.0 and bar_index > exitLen

if buySig {
    inPos := 1.0
}
if sellSig {
    inPos := 0.0
}

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 0, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1, "3d")
}

plot(entryLevel, "Entry 20H", "#22cc88", 1, "stepline")
plot(exitLevel, "Exit 10L", "#ff4477", 1, "stepline")
plot3d(entryLevel, "Entry 20H 3D", "line3d", "#22cc88", "3d", 0)
plot3d(exitLevel, "Exit 10L 3D", "line3d", "#ff4477", "3d", 1)

length = input(22, "Highest/Lowest Length", 2, 100, 1)
atrLen = input(22, "ATR Length", 1, 100, 1)
mult = input(3.0, "ATR Multiplier", 0.5, 10.0, 0.1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ATR: Wilder RMA — validated vs TradingView
atrVal = atr(atrLen)
hh = highest(high, length)
ll = lowest(low, length)
rawLong = hh - mult * atrVal
rawShort = ll + mult * atrVal
warm = bar_index > atrLen

var longTrail = 0.0
var shortTrail = 0.0

if warm {
    if close > longTrail[1] {
        longTrail := max(rawLong, longTrail[1])
    } else {
        longTrail := rawLong
    }
    if close < shortTrail[1] and shortTrail[1] > 0.0 {
        shortTrail := min(rawShort, shortTrail[1])
    } else {
        shortTrail := rawShort
    }
} else {
    longTrail := rawLong
    shortTrail := rawShort
}

longExit = warm and crossunder(close, longTrail)
shortExit = warm and crossover(close, shortTrail)

if longExit {
    plotshape(bar_index, high, "Exit Long", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Exit Long", "conedown", "#ff4477", markerSize, 0, "3d")
}

if shortExit {
    plotshape(bar_index, low, "Exit Short", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Exit Short", "coneup", "#22cc88", markerSize, 1, "3d")
}

plot(longTrail, "Chandelier Long", "#ff4477", 1, "stepline")
plot(shortTrail, "Chandelier Short", "#22cc88", 1, "stepline")
plot3d(longTrail, "Chandelier Long 3D", "line3d", "#ff4477", "3d", 0)
plot3d(shortTrail, "Chandelier Short 3D", "line3d", "#22cc88", "3d", 1)

fastLen = input(9, "Fast EMA", 2, 100, 1)
midLen = input(21, "Mid EMA", 3, 200, 1)
slowLen = input(55, "Slow EMA", 5, 300, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

fastMa = ema(close, fastLen)
midMa = ema(close, midLen)
slowMa = ema(close, slowLen)

bullStack = fastMa > midMa and midMa > slowMa
bearStack = fastMa < midMa and midMa < slowMa
bullPrev = bullStack[1]
bearPrev = bearStack[1]

buySig = bullStack and not bullPrev
sellSig = bearStack and not bearPrev
exitLong = crossunder(fastMa, midMa)
exitShort = crossover(fastMa, midMa)

if buySig {
  plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
  plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if exitLong and not buySig {
  plotshape(bar_index, high, "Exit Long", "diamond", "#ffcc00")
}
if exitShort and not sellSig {
  plotshape(bar_index, low, "Exit Short", "diamond", "#00ccff")
}
if buySig {
  plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "3d")
}
if sellSig {
  plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 0, "3d")
}

plot(fastMa, "Fast EMA", "#22cc88", 2, "line")
plot(midMa, "Mid EMA", "#ffcc00", 2, "line")
plot(slowMa, "Slow EMA", "#ff4477", 2, "line")
plot3d(fastMa, "Fast 3D", "ribbon", "#22cc88", "3d")
plot3d(slowMa, "Slow 3D", "line3d", "#ff4477", "3d", 1)
